int bluetooth_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int err = 0;
    struct sock *sk = sock->sk;
    int len;

    if (sk == NULL)
        return -EINVAL;

    if (level != SOL_BLUETOOTH)
        return -ENOPROTOOPT;

    switch (optname) {
    case BT_SECURITY:
    case BT_SECURITY_DEFAULT:
    case BT_SECURITY_REALM:
        len = sizeof(int);
        if (get_user(len, optlen))
            return -EFAULT;
        if (len < sizeof(int))
            return -EINVAL;
        if (put_user(sk->sec_level, (int __user *)optval))
            return -EFAULT;
        break;
    case BT_DEFER_SETUP:
        len = sizeof(int);
        if (get_user(len, optlen))
            return -EFAULT;
        if (len < sizeof(int))
            return -EINVAL;
        if (put_user(sk->defer_setup, (int __user *)optval))
            return -EFAULT;
        break;
    default:
        return -ENOPROTOOPT;
    }

    if (put_user(len, optlen))
        return -EFAULT;

    return 0;
}

