int rfcomm_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    int len, val;
    int ret = 0;

    if (level != SOL_RFCOMM)
        return -EINVAL;

    switch (optname) {
    case RFCOMM_SECURITY:
        val = sock->sk->sk_security;
        len = sizeof(val);
        break;
    case RFCOMM_DEFER_SETUP:
        val = sock->sk->sk_defer_setup;
        len = sizeof(val);
        break;
    default:
        return -ENOPROTOOPT;
    }

    if (len == 0)
        return -ENOPROTOOPT;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    len = min_t(size_t, len, sizeof(val));

    if (put_user(val, optval))
        return -EFAULT;

    if (put_user(len, optlen))
        return -EFAULT;

    return ret;
}

int bt_rfcomm_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    struct sock *sk = sock->sk;
    int len;
    int val;
    int err = 0;

    if (level != SOL_BLUETOOTH && level != SOL_RFCOMM)
        return -EINVAL;

    switch (optname) {
    case BT_SECURITY:
        val = sk->sk_security;
        len = sizeof(val);
        break;

    case RFCOMM_DEFER_SETUP:
        val = sk->sk_user_data;
        len = sizeof(val);
        break;

    default:
        return -ENOPROTOOPT;
    }

    if (put_user(len, optlen))
        return -EFAULT;

    if (copy_to_user(optval, &val, len))
        return -EFAULT;

    return 0;
}

